export const GLOSSARY_SHARD = Object.freeze({"satoshi":{"slug":"satoshi","cat":"basics","en":"Satoshi (sats)","contentLocale":"zh-Hans","term":"聪（Satoshi，sats）","aka":["sats","Satoshi","sat"],"short":"聪是比特币的最小单位，1 BTC 等于 1 亿聪，以比特币创始人中本聪命名，英文常写作 sats。","body":[["因为",["比特币","bitcoin"],"单价很高，用整数“几枚 BTC”来表达小额金额很不方便，于是很多人改用“聪”来计数。1 聪 = 0.00000001 BTC，也就是小数点后第 8 位。比特币链上的手续费率也常以“聪/字节”或 sat/vB 表示。"],["用聪来理解比特币，能帮你摆脱“比特币太贵买不起”的误区。",["交易所","centralized-exchange"],"买卖时通常显示的是 BTC 的小数，但它们背后都是以聪为单位记账的，只是展示方式不同。"],"有些钱包和闪电网络应用直接以 sats 显示余额，适合小额支付。不同交易所对 BTC 的最小下单数量和精度有各自规定，下单前可以在交易规则页面查看。"],"example":["假设 BTC 价格为 80,000 ",["USDT","usdt"],"，那么 1 聪的价值是 80,000 ÷ 100,000,000 = 0.0008 USDT。如果你用 40 USDT 买入，得到 40 ÷ 80,000 = 0.0005 BTC，即 50,000 聪。再比如链上手续费率为 10 sat/vB、交易大小为 140 vB，手续费就是 1,400 聪，约合 1.12 USDT。"],"mistakes":["数错小数点位数，把 0.0005 BTC 误算成 5,000 聪或 500 万聪。","以为聪是另一种独立的币，其实它只是比特币的计量单位。","提币时只看 BTC 数量而忽略以聪计算的网络手续费。"],"faq":[{"q":"1 比特币等于多少聪？","a":"1 BTC 等于 100,000,000 聪，也就是 1 亿聪。"},{"q":"为什么叫“聪”？","a":"名字来自比特币创造者的化名中本聪（Satoshi Nakamoto），中文取其中的“聪”字作为单位名。"}],"title":"聪（sats）是什么？1 比特币等于多少聪","description":"聪是比特币的最小单位：1 BTC 等于 1 亿聪。本文用例子讲清聪和 BTC 怎么换算、手续费 sat/vB 是什么意思。","related":[["bitcoin","比特币（Bitcoin，BTC）","比特币是 2009 年上线的第一个去中心化加密货币，总量上限 2100 万枚，通过工作量证明挖矿维护网络，代号 BTC。"],["dollar-cost-averaging","定投（DCA）","定投（DCA）是按固定周期、用固定金额买入同一资产的策略，不去猜测高低点，借助分批买入摊平成本、降低一次性买在高位的风险。"],["market-order","市价单（Market Order）","市价单是以当前市场上最优可得价格立即成交的订单，优点是成交快、几乎一定成交，缺点是无法控制成交价格。"],["cryptocurrency","加密货币（Cryptocurrency）","加密货币是依靠密码学和区块链记账、无需银行等中心机构即可点对点转移的数字资产，比特币是第一个加密货币。"]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"一枚比特币太贵，我就不能买吗？"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"fomo":{"slug":"fomo","cat":"basics","en":"FOMO","contentLocale":"zh-Hans","term":"FOMO（错失恐惧）","aka":["错失恐惧症","怕踏空","Fear of missing out"],"short":"FOMO（Fear of Missing Out）指害怕错过上涨行情而冲动买入的心理，在币圈常表现为追高和临时加仓。","body":[["当某个币连续大涨、社交媒体上到处是晒收益的截图时，人很容易产生“再不买就来不及了”的焦虑。FOMO 让人跳过原本的计划，用",["市价单","market-order"],"追在高位，或把原本不打算投入的钱也投进去。"],"FOMO 常见于行情加速上涨的阶段，而这恰恰往往是波动最大的时候。追高买入后，一次 10% 到 20% 的正常回调就可能让人恐慌卖出，最后高买低卖。",["应对 FOMO 的实用方法是把决策提前：买之前写下买入理由、仓位上限、止损位置和退出条件；对想追的币设置",["限价单","limit-order"],"或分批买入，而不是一次性梭哈。"]],"example":["假设某币一周内从 1 ",["USDT","usdt"]," 涨到 1.8 USDT，你在 1.75 USDT 用市价单追入 2,000 USDT，得到约 1,143 枚。随后价格回调到 1.4 USDT，跌幅 20%，你的仓位剩约 1,600 USDT。你恐慌卖出，亏损 400 USDT 加手续费。若你按计划只投入 500 USDT 并分三次在 1.75、1.6、1.45 买入，平均成本约 1.59 USDT，回调时的压力会小很多。"],"mistakes":["看到涨幅榜第一就立刻市价买入，不做任何研究。","把原本预留的生活费也投进去追涨。","追高后没设止损，跌了又恐慌割肉。"],"faq":[{"q":"FOMO 是什么意思？","a":"FOMO 是 Fear of Missing Out 的缩写，意为害怕错过。币圈常用来形容看到别人赚钱就冲动追涨的情绪。"},{"q":"FOMO 和 FUD 有什么关系？","a":"两者方向相反：FOMO 是怕错过上涨而追买，FUD 是被恐惧和不确定消息影响而抛售，都是情绪驱动的交易。"}],"title":"FOMO 是什么意思？币圈追高心理解析","description":"FOMO（错失恐惧）在币圈是什么意思？讲清 FOMO 如何导致追高和高买低卖，并用例子说明分批买入和预设计划的作用。","related":[["fud","FUD（恐惧、不确定、怀疑）","FUD 是 Fear、Uncertainty、Doubt 的缩写，指在市场上传播的恐惧、不确定和怀疑情绪或消息，常引发恐慌性抛售。"],["bull-market","牛市（Bull Market）","牛市是指加密货币或其他资产价格在较长时间内持续上涨、成交活跃、市场情绪普遍乐观的阶段，与之相对的是熊市。"],["position-sizing","仓位管理（Position Sizing）","仓位管理是根据账户总资金、可承受的单笔亏损和止损距离，计算每笔交易应该开多大仓位的方法，目的是让任何一笔交易都不会重伤账户。"],["fear-and-greed-index","恐惧与贪婪指数（Fear and Greed Index）","恐惧与贪婪指数是把价格波动、成交量、社交媒体热度、资金费率等数据综合成0到100分数的市场情绪指标，分数越低代表越恐惧，越高代表越贪婪。"],["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。"]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"先想能亏多少，再决定买多少"},"coin":null,"tool":null,"cta":false},"wash-trading":{"slug":"wash-trading","cat":"trading","en":"Wash trading","contentLocale":"zh-Hans","term":"刷量（Wash Trading）","aka":["对敲","虚假成交","wash trading"],"short":"刷量是指同一方或串通的几方自己买卖自己的订单，制造虚假的成交量和活跃度，让一个币或一家交易所看起来比实际更热门。","body":[["刷量的成交并不改变资产的真实持有人，只是钱和币在同一控制人的账户之间来回转。目的通常是提高",["交易所","centralized-exchange"],"的",["成交量","trading-volume"],"排名、让新币看起来交投活跃以吸引跟风，或者在 ",["NFT","nft"]," 市场里抬高地板价和交易记录。"],["刷量的危害在于误导判断：你看到很高的成交量，以为随时能按市价买卖，实际",["订单簿","order-book"],"可能非常薄，真正下单时",["滑点","slippage"],"巨大。在不少国家和地区，操纵市场的行为受到监管，但各地规定和执法力度不同。"],["识别刷量可以看几个信号：成交量和订单簿深度严重不匹配；成交量占",["市值","market-capitalization"],"比例长期异常高；成交记录里大量同样数量、同样间隔的小单；同一个币在主流交易所成交平淡，只在个别平台成交量极高。"]],"example":"假设某个交易对一天的真实成交只有 50 万 USDT，但项目方用两个账户互相买卖，又刷出 1,000 万 USDT。页面显示 24 小时成交量 1,050 万 USDT，其中约 95% 是虚假的。你看到这个数字，以为卖出 20 万 USDT 很轻松，实际一挂单就会把价格砸下去好几个百分点。","mistakes":["把交易所排行榜上的成交量当作真实热度，不看订单簿深度。","看到新币上线后成交量暴涨，就认为有大量真实买盘。","只看单一平台数据，不和主流交易所的成交情况对比。"],"faq":[{"q":"刷量违法吗？","a":"在许多司法辖区，刷量属于操纵市场，受到证券或金融监管规则约束，但加密资产的适用规则因国家和地区而异。"},{"q":"怎么看出一个币在刷量？","a":"对比成交量和订单簿深度、成交量与市值的比例，并查看成交明细里是否有大量机械化的重复订单。主流交易所之间数据差距过大也是信号。"}],"title":"什么是刷量（Wash Trading）？如何识别虚假成交量","description":"了解刷量和对敲是什么、项目方和交易所为什么要刷量，以及如何通过订单簿深度和成交明细识别虚假的成交量数据。","related":[["trading-volume","成交量（Trading Volume）","成交量是在一段时间内实际成交的资产数量或金额，例如 24 小时成交量，用来衡量一个币或一个市场的交易活跃程度。"],["liquidity","流动性（Liquidity）","流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。"],["proof-of-reserves","储备金证明（Proof of Reserves）","储备金证明（PoR）是交易所公开证明自己持有的用户资产储备至少等于用户存款总额的做法，通常结合默克尔树和链上地址来让用户自行核验。"],["market-maker","做市商（Market Maker）","做市商是在订单簿上持续同时挂出买单和卖单、为市场提供流动性的交易者或机构，主要通过买卖价差和交易所的挂单返佣获利。"]],"lesson":null,"coin":null,"tool":"/exchanges","cta":false},"whale":{"slug":"whale","cat":"trading","en":"Whale","contentLocale":"zh-Hans","term":"巨鲸（Whale）","aka":["鲸鱼","大户","whale"],"short":"巨鲸是指持有某种加密资产数量极大的个人或机构地址，他们的买卖或转账规模足以影响市场价格和情绪。","body":[["多大才算巨鲸没有统一标准，不同币种和数据平台的划分不同，常见的说法是持有上千枚 ",["BTC","bitcoin"]," 的地址。巨鲸可能是早期持有者、基金、",["交易所","centralized-exchange"],"或项目方，一个地址也不一定对应一个人，交易所的",["冷钱包","cold-wallet"],"同样会显示为“巨鲸地址”。"],["因为",["区块链","blockchain"],"是公开账本，巨鲸的大额转账可以被",["链上分析","on-chain-analysis"],"工具追踪，常被称为“巨鲸异动”。大额币转入交易所，常被解读为可能卖出；从交易所转出到个人钱包，常被解读为",["长期持有","hodl"],"。"],"但这些只是线索，不是结论。转账可能是交易所内部钱包整理、托管机构调仓或场外交易交割。巨鲸在订单簿上的大单也可能只是挂着影响情绪，随时撤掉。"],"example":"假设链上监测显示某地址把 5,000 BTC 转入一家交易所，按 60,000 USDT 计算约 3 亿 USDT。社群里立刻有人喊“巨鲸要砸盘”。但如果这个地址之后只是转到该交易所的另一个冷钱包，价格并不会受影响。反过来，如果他真的在订单簿上市价卖出 500 BTC，在深度一般的交易对上可能直接把价格砸下几个百分点。","mistakes":["看到巨鲸转入交易所就立刻跟着卖出，不确认地址身份和后续动向。","把交易所冷钱包或托管地址当成个人巨鲸。","相信订单簿上的巨额挂单一定会成交，忽略它可能随时被撤销。"],"faq":[{"q":"持有多少比特币算巨鲸？","a":"没有官方标准，很多数据平台把持有 1,000 枚 BTC 以上的地址视为巨鲸，不同平台的门槛不一样。"},{"q":"巨鲸转币到交易所一定会砸盘吗？","a":"不一定。转入交易所可能是为了卖出，也可能是做抵押、内部整理或场外交割，需要结合后续链上动向和市场成交来判断。"}],"title":"币圈巨鲸是什么意思？如何看巨鲸异动","description":"解释币圈“巨鲸”（大户）的含义、如何通过链上数据追踪巨鲸转账，以及为什么巨鲸异动不能直接当作买卖信号。","related":[["on-chain-analysis","链上分析（On-chain analysis）","链上分析是通过研究区块链上公开记录的转账、地址余额、交易所资金流向等数据，来判断市场参与者行为和资金动向的分析方法。"],["exchange-netflow","交易所净流入/净流出（Exchange netflow）","交易所净流入/净流出是指一段时间内转入中心化交易所的某种加密资产数量减去从交易所转出的数量，用来观察资金是在涌向交易所还是离开交易所。"],["liquidity","流动性（Liquidity）","流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。"],["slippage","滑点（Slippage）","滑点是指订单实际成交价格与下单时预期价格之间的差异，常发生在市价单、大额交易、流动性差或行情剧烈波动时。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"margin-call":{"slug":"margin-call","cat":"derivatives","en":"Margin call","contentLocale":"zh-Hans","term":"追加保证金（Margin Call）","aka":["追保","补仓提醒","margin call"],"short":"追加保证金是指仓位亏损使保证金接近维持要求时，交易所发出风险提醒，要求你补充保证金或减仓，否则仓位可能被强制平仓。","body":[["在传统期货和券商融资中，追保通知后通常有一段时间让你补钱。",["加密货币","cryptocurrency"],["交易所","centralized-exchange"]," 7×24 小时运行，价格变化很快，追保提醒往往只是一条推送或邮件，",["强平","liquidation"],"可能在几分钟甚至几秒后发生，不能指望有时间慢慢处理。"],["交易所一般用保证金率或风险率来衡量危险程度。以一种常见定义为例：保证金率 = ",["维持保证金","maintenance-margin"]," ÷ 账户权益，达到 100% 时触发强平，接近时发出提醒。不同交易所的公式和阈值不同，有的用相反方向的风险率，请以自己交易所的说明为准。"],["应对追保有三种办法：追加保证金、部分平仓降低仓位，或者在",["逐仓模式","isolated-margin"],"下给单个仓位增加保证金。更好的做法是开仓时就留足空间，并设置止损，而不是等提醒来了再决定。"]],"example":["假设你的全仓账户权益为 4,000 ",["USDT","usdt"],"，持仓所需维持保证金 800 USDT，保证金率 20%。行情下跌后权益降到 1,000 USDT，保证金率升到 80%，交易所发出风险提醒。如果你追加 1,000 USDT，权益变成 2,000，保证金率回到 40%。如果什么也不做，权益再降到 800，保证金率达到 100%，仓位被强平。"],"mistakes":["以为收到追保提醒后还有几个小时可以处理。","不断追加保证金死扛亏损仓位，让小亏变成大亏。","关掉交易所通知，错过风险提醒。"],"faq":[{"q":"加密货币交易所会打电话追保吗？","a":"通常不会，一般是 App 推送、短信或邮件提醒，而且强平由系统自动执行，可能来得非常快。"},{"q":"收到追保提醒应该怎么办？","a":"先判断原来的交易计划是否还成立。如果止损条件已经触发，减仓或平仓通常比追加保证金更合理；追加保证金只是推迟强平价，并不减少亏损。"}],"title":"追加保证金是什么？币圈追保和强平的关系","description":"解释加密货币交易中追加保证金（Margin Call）的含义、保证金率怎么看、收到追保提醒后的几种处理方式，以及常见误区。","related":[["maintenance-margin","维持保证金（Maintenance Margin）","维持保证金是持有合约仓位所需的最低保证金，当仓位的保证金余额（含未实现盈亏）跌到这个水平时，交易所会触发强制平仓。"],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"],["cross-margin","全仓保证金（Cross Margin）","全仓保证金是一种保证金模式，账户内所有可用余额共同为全部全仓仓位提供保证金，抗波动能力更强，但一旦强平可能亏掉整个账户余额。"],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"保证金为什么还没归零，就可能出局？"},"coin":null,"tool":"/liquidations","cta":false},"liquidation":{"slug":"liquidation","cat":"derivatives","en":"Liquidation","contentLocale":"zh-Hans","term":"强平（Liquidation）","aka":["爆仓","强制平仓","清算","liquidation"],"short":"强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。","body":[["强平的触发条件通常基于",["标记价格","mark-price"],"：当仓位的保证金余额加上",["未实现盈亏","unrealized-pnl"],"，跌到",["维持保证金","maintenance-margin"],"以下，系统就会接管仓位。很多",["交易所","centralized-exchange"],"会先尝试部分减仓，降低风险档位，仍不足时再全部平仓。"],["被强平后，你通常会失去这个仓位的大部分或全部保证金，部分交易所还会收取强平手续费。如果强平引擎以优于破产价格的价格平掉仓位，多出来的部分一般进入",["风险保障基金","insurance-fund"],"；如果市场太剧烈、平仓价格比破产价格更差，亏损先由保障基金承担，不足时可能触发",["自动减仓（ADL）","auto-deleveraging"],"。"],"强平是合约交易最常见的亏损方式之一。避免强平的核心不是“扛”，而是控制仓位大小、降低实际杠杆、设置止损，并留意资金费率和极端行情下的插针。"],"example":"假设你有 1,000 USDT，用 50 倍杠杆在 60,000 开 BTC 多单，仓位价值 50,000 USDT，约 0.833 BTC。维持保证金率 0.5%，需要 250 USDT。当浮亏达到 750 USDT，即 BTC 下跌约 1.5%、跌到 59,100 左右时，仓位就会被强平。一根普通的 1 分钟K线就可能有这么大的波动。","mistakes":["以为价格只是“暂时跌一下”，不止损死扛，结果在低点附近被强平。","用最新成交价估算强平距离，忽略系统以标记价格判断。","不知道强平后可能还要支付强平手续费，实际损失比预想的更多。"],"faq":[{"q":"爆仓和强平是一回事吗？","a":"日常说法里基本是一回事，都是指仓位因保证金不足被系统强制平仓。有时“穿仓”则特指亏损超过了保证金。"},{"q":"爆仓后会欠交易所钱吗？","a":"大多数主流交易所的合约会用风险保障基金和自动减仓机制处理穿仓损失，普通用户一般不会因此负债，但具体规则以交易所条款为准。"},{"q":"怎么避免被强平？","a":"降低实际杠杆、控制仓位大小、设置止损，并在全仓与逐仓之间做出合适选择，比事后追加保证金更有效。"}],"title":"强平是什么？合约爆仓的原因与避免方法","description":"解释合约交易中强平（爆仓）的触发条件、强平后保证金和保险基金如何处理，以及控制杠杆和止损避免爆仓的实用方法。","related":[["liquidation-price","强平价（Liquidation Price）","强平价是标记价格达到后会触发仓位强制平仓的价格，由开仓价、杠杆倍数、维持保证金率以及保证金模式共同决定。"],["maintenance-margin","维持保证金（Maintenance Margin）","维持保证金是持有合约仓位所需的最低保证金，当仓位的保证金余额（含未实现盈亏）跌到这个水平时，交易所会触发强制平仓。"],["mark-price","标记价格（Mark Price）","标记价格是交易所用来计算未实现盈亏和判断强平的参考价格，通常以多家现货交易所的指数价格为基础，比最新成交价更难被短时操纵。"],["insurance-fund","风险保障基金（Insurance Fund）","风险保障基金是合约交易所设立的资金池，用来弥补被强平仓位以差于破产价格成交时产生的穿仓损失，避免盈利方的收益受到影响。"],["auto-deleveraging","自动减仓（ADL）","自动减仓（ADL）是合约交易所在强平仓位无法以足够好的价格平掉、风险保障基金又不足以弥补亏损时，按排名强制减少对手方盈利仓位的风控机制。"]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"爆仓：谁按下了强制平仓按钮？"},"coin":null,"tool":"/liquidations","cta":false},"liquidation-price":{"slug":"liquidation-price","cat":"derivatives","en":"Liquidation price","contentLocale":"zh-Hans","term":"强平价（Liquidation Price）","aka":["强平价格","爆仓价","liquidation price"],"short":"强平价是标记价格达到后会触发仓位强制平仓的价格，由开仓价、杠杆倍数、维持保证金率以及保证金模式共同决定。","body":[["开仓后",["交易所","centralized-exchange"],"会直接显示预估强平价。",["逐仓模式","isolated-margin"],"下，强平价只取决于这个仓位自身的保证金；",["全仓模式","cross-margin"],"下，账户余额和其他仓位的盈亏都会影响强平价，所以它会随时变化。"],["逐仓、单一仓位、忽略手续费时，可以用简化公式估算。多单：强平价 ≈ 开仓价 × (1 − 1/",["杠杆","leverage"],") ÷ (1 − ",["维持保证金率","maintenance-margin"],")；空单：强平价 ≈ 开仓价 × (1 + 1/杠杆) ÷ (1 + 维持保证金率)。实际数值还受手续费、阶梯维持保证金率和交易所算法影响，以交易所显示为准。"],["强平价离开仓价越近，越容易被正常波动甚至插针触发。",["追加保证金","margin-call"],"或降低仓位可以把强平价推远；在全仓模式下，提走余额会让强平价变近。"]],"example":"假设你在 3,000 USDT 开 ETH 多单，逐仓 10 倍杠杆，维持保证金率 0.5%。估算强平价 ≈ 3,000 × 0.9 ÷ 0.995 ≈ 2,714 USDT，比开仓价低约 9.5%。同样条件开空单，强平价 ≈ 3,000 × 1.1 ÷ 1.005 ≈ 3,284 USDT。如果杠杆换成 50 倍，多单强平价会升到约 2,955，只差 1.5%。","mistakes":["以为 10 倍杠杆要跌满 10% 才会强平，忽略维持保证金。","在全仓模式下提走余额，没注意强平价随之靠近。","把止损设在强平价之外，止损还没触发仓位就已经被强平。"],"faq":[{"q":"强平价是按最新价还是标记价格触发？","a":"绝大多数交易所的合约以标记价格触发强平，这样可以减少单个交易所插针导致的误强平。"},{"q":"强平价会变吗？","a":"逐仓模式下，只要不追加或减少保证金，强平价基本不变；全仓模式下，账户余额和其他仓位的盈亏变化都会让强平价移动。"}],"title":"强平价怎么算？合约爆仓价格计算公式","description":"解释合约强平价（爆仓价）由哪些因素决定，用简化公式和实例计算多单与空单的强平价，并说明逐仓和全仓的差异。","related":[["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"],["isolated-margin","逐仓保证金（Isolated Margin）","逐仓保证金是一种保证金模式，每个仓位只使用单独分配给它的保证金，仓位被强平时最多亏掉这部分，不会动用账户里的其他资金。"],["mark-price","标记价格（Mark Price）","标记价格是交易所用来计算未实现盈亏和判断强平的参考价格，通常以多家现货交易所的指数价格为基础，比最新成交价更难被短时操纵。"],["maintenance-margin","维持保证金（Maintenance Margin）","维持保证金是持有合约仓位所需的最低保证金，当仓位的保证金余额（含未实现盈亏）跌到这个水平时，交易所会触发强制平仓。"]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"爆仓：谁按下了强制平仓按钮？"},"coin":null,"tool":"/liquidations","cta":false},"long-short-ratio":{"slug":"long-short-ratio","cat":"derivatives","en":"Long/short ratio","contentLocale":"zh-Hans","term":"多空比（Long/Short Ratio）","aka":["多空比例","账户多空比","long short ratio"],"short":"多空比是交易所统计的持有多单用户（或多单持仓）与持有空单用户（或空单持仓）之间的比例，用来观察散户或大户在某个合约上的情绪偏向。","body":[["一个关键常识：在整个合约市场里，多单和空单的总",["持仓量","open-interest"],"永远相等，每份多单都有一份空单作为对手。所以多空比衡量的不是“多单比空单多”，而是不同人群的分布，比如有多少账户偏多，或者",["交易所","centralized-exchange"],"定义的大户账户偏向哪边。"],"常见的多空比有几种口径：按账户数统计的多空人数比、按持仓量统计的大户持仓多空比等。不同交易所的定义、统计范围和更新频率都不一样，跨平台对比前要看清楚说明。",["多空比常被当作反向指标使用：大量账户一边倒地做多时，市场可能存在拥挤的多头，一旦下跌容易连环",["强平","liquidation"],"。但它不是独立的买卖信号，需要配合持仓量、",["资金费率","funding-rate"],"和价格结构一起看。"]],"example":["假设某交易所显示 ",["BTC","bitcoin"]," 永续的账户多空比为 2.5，意思是持有多单的账户数是持有空单账户数的 2.5 倍，约 71.4% 的账户偏多、28.6% 的账户偏空。但多空总持仓量仍然相等，这说明少数空单账户平均持仓更大，可能是大户或做市机构在另一边。"],"mistakes":["以为多空比大于 1 就说明市场里多单总量比空单多。","把多空比当作直接的买卖信号，看到偏多就开空。","混用不同交易所、不同口径的多空比数据。"],"faq":[{"q":"多空比高是看涨还是看跌？","a":"多空比高只说明更多账户持有多单，很多人把它看作多头拥挤的提示，但它本身不能预测方向，需要结合其他数据。"},{"q":"为什么多单和空单总量相等，多空比却不是 1？","a":"因为多空比通常按账户数或特定人群统计，而不是按全市场总持仓。少数账户可能持有很大的空单，与大量小额多单账户对应。"}],"title":"多空比是什么？合约多空比例怎么看","description":"解释合约多空比的含义和几种统计口径、为什么多单空单总量永远相等，以及如何结合持仓量和资金费率解读多空情绪。","related":[["open-interest","持仓量（Open Interest）","持仓量是某个合约市场中所有尚未平仓的合约总量，每一份多单都对应一份空单，它衡量的是有多少资金仍然留在市场里。"],["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"],["long-and-short","做多与做空（Long and Short）","做多是预期价格上涨而买入或开多单，价格上涨时盈利；做空是预期价格下跌而卖出或开空单，价格下跌时盈利，两者是交易的两个基本方向。"],["short-squeeze","轧空（Short Squeeze）","轧空是指价格上涨迫使大量空头止损或被强平，他们的平仓买单又进一步推高价格，形成连锁反应、价格在短时间内急速拉升的现象。"]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"anti-phishing-code":{"slug":"anti-phishing-code","cat":"wallets-security","en":"Anti-phishing code","contentLocale":"zh-Hans","term":"防钓鱼码（Anti-phishing Code）","aka":["防钓鱼码","反钓鱼码","Anti-phishing code"],"short":"防钓鱼码是你在交易所设置的一段自定义文字，之后平台发来的官方邮件里都会带上它，用来帮你分辨真假邮件，识别冒充交易所的钓鱼信息。","body":[["骗子常常伪造",["交易所","centralized-exchange"],"邮件，比如“账户异常，请点击链接验证”，外观和官方几乎一样。设置防钓鱼码后，真正由交易所发出的邮件都会显示你设定的那几个字，冒充者不知道这个码，就无法伪造。"],"设置路径通常在“安全中心”里，内容随你定，最好是别人猜不到、和账户信息无关的词。部分交易所的防钓鱼码也会出现在短信或站内信里，覆盖范围以平台说明为准。","它只解决“这封邮件是不是官方发的”这一个问题。即便邮件是真的，也不要从邮件链接直接登录，养成从书签或官方 App 打开的习惯更稳妥。"],"example":["假设你把防钓鱼码设为“青柠7号”。某天收到一封标题为“您的提现已被冻结，请在 24 小时内验证”的邮件，排版、Logo 都很像真的，但邮件正文里没有“青柠7号”这 4 个字。你据此判断它是钓鱼邮件，直接删除，而不是点击链接输入账号、密码和 ",["2FA","two-factor-authentication"]," 码。"],"mistakes":["设置了防钓鱼码却从不看邮件里有没有它。","把防钓鱼码设成手机号、生日或账户昵称，容易被猜到。","看到带有防钓鱼码的邮件就放心点开所有链接，忽略了其他风险。"],"faq":[{"q":"防钓鱼码能防止账户被盗吗？","a":"它不能直接阻止盗号，只帮你识别假冒邮件。账户安全还要依靠强密码、2FA 和提现白名单等措施配合。"},{"q":"收到没有防钓鱼码的邮件怎么办？","a":"不要点其中的链接或附件。直接打开官方 App 或手动输入官网查看是否真有通知，必要时向官方客服举报。"}],"title":"防钓鱼码是什么？如何识别交易所钓鱼邮件","description":"防钓鱼码是什么意思？了解交易所防钓鱼码的作用、设置方法和使用习惯，学会快速分辨真假官方邮件，避免点进钓鱼网站。","related":[["phishing","钓鱼攻击（Phishing）","钓鱼攻击是指诈骗者冒充交易所、钱包或项目方，通过假网站、假邮件、假客服诱导你交出密码、验证码、助记词或签下恶意授权，从而盗取资产。"],["two-factor-authentication","双重验证（2FA）","双重验证（2FA）是在密码之外再加一道验证的登录与操作保护，常见形式有验证器 App 动态码、短信验证码和硬件安全密钥。"],["withdrawal-whitelist","提币白名单（Withdrawal Whitelist）","提币白名单是交易所的一项安全设置，开启后账户只能向你事先登记并验证过的地址提币，即使账户被盗，对方也难以把资产转到陌生地址。"]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"先认门，再注册：别把账户开在假平台"},"coin":null,"tool":null,"cta":false},"pig-butchering-scam":{"slug":"pig-butchering-scam","cat":"wallets-security","en":"Pig-butchering scam","contentLocale":"zh-Hans","term":"杀猪盘","aka":["杀猪盘骗局","投资诈骗","Pig butchering"],"short":"杀猪盘是一种长期设局的诈骗，骗子先通过交友、恋爱或“带单”建立信任，再引导你在虚假平台投资加密货币，等你投入越来越多后卷款消失。","body":["骗子通常在交友软件、社交平台或“加错微信”中主动搭讪，花几周甚至几个月建立感情或师徒关系，这一阶段叫“养猪”。随后他们会展示自己的“盈利截图”，推荐一个看起来很专业的交易平台或 App，这个平台往往是骗子自己控制的。","开始时你小额投入，后台数字显示大幅盈利，甚至允许你提出一小笔，让你更加相信。等你加大投入、拉亲友入金后，平台就会以“交税”“保证金”“账户冻结需解冻费”等理由不让提现，最后彻底失联。","识别信号：网上认识的人主动带你投资；平台不在主流应用商店或域名可疑；收益高得离谱且稳定；提现要先交费。遇到这些情况，应停止转账，保留聊天和转账记录并及时报警。"],"example":["假设你被网友拉进一个“内部合约平台”，先充值 1,000 ",["USDT","usdt"],"，三天后账面显示 1,600 USDT，还成功提出了 200 USDT。你随后又充了 20,000 USDT，账面显示涨到 32,000 USDT，但申请提现时被告知需先缴纳 20% 的“个人所得税”，也就是 6,400 USDT。这正是杀猪盘的典型收网步骤，你交了这笔钱也依然无法提现。"],"mistakes":["因为第一次小额提现成功，就相信平台真实可靠。","按照“导师”的指示下载非官方 App 或通过链接进入交易平台。","为了取回本金，继续按要求缴纳各种“税费”“解冻费”。"],"faq":[{"q":"杀猪盘的钱能追回吗？","a":"难度很大，因为资金通常很快被转移和混币。尽早报警并提供交易哈希、收款地址和聊天记录，能提高部分冻结的可能，但没有保证。"},{"q":"如何判断投资平台是不是正规交易所？","a":"从主流应用商店或官网直接下载，核对公司主体与监管信息，并查询是否有大量用户能正常充提，不要通过陌生人提供的链接注册。"}],"title":"什么是杀猪盘？加密货币杀猪盘的套路与识别","description":"杀猪盘是什么意思？拆解杀猪盘从交友、带单、小额盈利到要求交税收网的完整套路，教你识别虚假平台和关键危险信号。","related":[["phishing","钓鱼攻击（Phishing）","钓鱼攻击是指诈骗者冒充交易所、钱包或项目方，通过假网站、假邮件、假客服诱导你交出密码、验证码、助记词或签下恶意授权，从而盗取资产。"],["rug-pull","跑路（Rug Pull）","Rug Pull（跑路、拉地毯）是指项目方在吸引投资者买入后，突然撤走流动性池中的资金、大量抛售手中代币或卷走资金，导致代币价格瞬间归零。"],["p2p-trading","P2P交易（C2C交易）","P2P交易（币圈常称C2C）是指用户之间在交易所提供的撮合平台上直接买卖加密资产，买方通过银行转账等方式付款给卖方，平台托管卖方的币作为担保。"],["seed-phrase","助记词（Seed Phrase）","助记词是由 12 或 24 个英文单词组成的钱包备份，可以推导出钱包里的全部私钥，谁拿到助记词，谁就能控制这个钱包里的所有资产。"]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"别人说能帮你赚钱，先看他要什么"},"coin":null,"tool":null,"cta":false},"hash-rate":{"slug":"hash-rate","cat":"onchain","en":"Hash rate","contentLocale":"zh-Hans","term":"算力（Hash rate）","aka":["哈希率","全网算力","Hash rate"],"short":"算力是矿机或整个工作量证明网络每秒能完成的哈希计算次数，常用TH/s、EH/s表示，全网算力越高，攻击网络所需的成本通常越高。","body":[["在",["比特币","bitcoin"],"这样的",["工作量证明（PoW）","proof-of-work"],"网络中，矿工要不断计算",["哈希值","transaction-hash"],"，寻找满足难度要求的结果才能打包区块、获得区块奖励。一台矿机的算力决定了它每秒能尝试多少次，单位从H/s、TH/s（万亿次）到EH/s（百亿亿次）。"],"全网算力是所有矿工算力的总和。比特币大约每2016个区块调整一次难度，让平均出块时间保持在10分钟左右：算力上升，难度随之提高；算力下降，难度降低。因此单个矿工的收益取决于他占全网算力的比例，而不是绝对算力。","算力常被视为网络安全程度和矿工投入的指标。减半之后区块奖励减少，电费高、设备旧的矿工可能关机，算力短期回落。算力数据是根据出块速度估算的，不同数据源的数字会有差别。"],"example":"假设全网算力为600 EH/s，你有一台200 TH/s的矿机。600 EH/s等于600,000,000 TH/s，你的份额是1/3,000,000。比特币一天约出144个区块，每块奖励3.125 BTC，全天约450 BTC。不计交易手续费和矿池费用，你的期望产出约为450 ÷ 3,000,000 = 0.00015 BTC。如果全网算力涨到750 EH/s，你的份额会下降，期望产出约降至0.00012 BTC。","mistakes":["只看矿机的算力，不考虑全网算力上升对收益的稀释。","把算力创新高直接等同于币价会上涨。","计算挖矿回报时忽略电费、矿池费用和难度调整。"],"faq":[{"q":"算力和币价有什么关系？","a":"两者有一定关联：币价上涨会吸引更多矿工加入、推高算力，但算力本身不能决定币价，常常滞后于价格变化。"},{"q":"以太坊还有算力吗？","a":"以太坊在2022年9月合并后转为权益证明，不再依靠挖矿，因此不再有算力指标，网络安全改由质押的ETH来保障。"}],"title":"什么是算力（Hash rate）？全网算力与挖矿收益","description":"算力是什么？了解TH/s和EH/s的含义、全网算力与难度调整的关系，并用实际计算演示矿机份额与期望收益。","related":[["mining","挖矿（Crypto Mining）","挖矿是在工作量证明区块链上用计算设备竞争打包区块、维护网络安全并获得新币奖励和手续费的过程。"],["proof-of-work","工作量证明（PoW）","工作量证明（PoW）是一种共识机制，矿工通过大量计算竞争求解哈希难题，最先找到答案的人获得出块权和奖励，比特币采用这种机制。"],["bitcoin-halving","比特币减半（Bitcoin Halving）","比特币减半是指每产出 21 万个区块（约四年）矿工的区块奖励自动减少一半的规则，2024 年 4 月减半后奖励降至 3.125 BTC。"],["on-chain-analysis","链上分析（On-chain analysis）","链上分析是通过研究区块链上公开记录的转账、地址余额、交易所资金流向等数据，来判断市场参与者行为和资金动向的分析方法。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"exchange-netflow":{"slug":"exchange-netflow","cat":"onchain","en":"Exchange inflows and outflows","contentLocale":"zh-Hans","term":"交易所净流入/净流出（Exchange netflow）","aka":["交易所净流量","交易所流入流出","Netflow"],"short":"交易所净流入/净流出是指一段时间内转入中心化交易所的某种加密资产数量减去从交易所转出的数量，用来观察资金是在涌向交易所还是离开交易所。","body":[["数据平台会给已知的",["交易所","centralized-exchange"],"地址打标签，再统计这些地址收到和发出的币。转入多于转出就是净流入，转出多于转入就是净流出。",["BTC","bitcoin"],"、ETH等主流币和USDT、USDC等",["稳定币","stablecoin"],"都可以单独统计。"],["常见的解读是：主流币大量净流入交易所，可能意味着持有人准备卖出，短期抛压增大；大量净流出，可能表示币被转到",["自托管钱包","non-custodial-wallet"],["长期持有","hodl"],"。稳定币则相反，大量稳定币净流入交易所，常被看作有买入资金在场内待命。"],"这些都只是可能性。交易所之间调拨、托管机构把币放进交易所做抵押、ETF托管方的资产转移，都会影响数据；部分交易所地址没有被标注，统计也不完整。所以净流量更适合看趋势和异常的大额变化，不宜单凭一天的数字做判断。"],"example":"假设某天流入各交易所的BTC共有12,000枚，从交易所流出的共15,000枚，净流量为负3,000枚，即净流出3,000枚。同一天交易所的USDT净流入5亿枚。单看这一天，信号偏向“币被提走、场内买入资金增加”。但如果你发现那3,000枚中有2,500枚流向了某托管机构的地址，那它更可能是机构业务操作，而不是散户长期囤币。","mistakes":["把一天的大额净流入直接当成马上会暴跌的信号。","不区分主流币和稳定币的净流向，读反了含义。","忽略交易所内部冷热钱包调拨和机构托管迁移造成的数据噪音。"],"faq":[{"q":"交易所净流出是利好吗？","a":"常被解读为偏利好，因为币离开交易所后短期可卖出的筹码减少，但它并不保证价格上涨，需要结合其他指标判断。"},{"q":"交易所净流量数据从哪里来？","a":"来自链上数据平台对交易所地址的标注和统计。各平台的标注范围不同，同一天的数字可能有出入。"}],"title":"交易所净流入净流出是什么意思？如何解读","description":"交易所净流入和净流出代表什么？了解主流币与稳定币资金流向的不同含义、常见解读方法以及数据中的干扰因素。","related":[["on-chain-analysis","链上分析（On-chain analysis）","链上分析是通过研究区块链上公开记录的转账、地址余额、交易所资金流向等数据，来判断市场参与者行为和资金动向的分析方法。"],["whale","巨鲸（Whale）","巨鲸是指持有某种加密资产数量极大的个人或机构地址，他们的买卖或转账规模足以影响市场价格和情绪。"],["proof-of-reserves","储备金证明（Proof of Reserves）","储备金证明（PoR）是交易所公开证明自己持有的用户资产储备至少等于用户存款总额的做法，通常结合默克尔树和链上地址来让用户自行核验。"],["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"active-addresses":{"slug":"active-addresses","cat":"onchain","en":"Active addresses","contentLocale":"zh-Hans","term":"活跃地址数（Active addresses）","aka":["日活地址","活跃地址","Active addresses"],"short":"活跃地址数是指在一定时间内（通常是一天）作为发送方或接收方参与过链上交易的不重复地址数量，常被用来粗略衡量一条区块链的使用热度。","body":["每当一个地址发送或接收一笔交易，它在当天就算一次活跃，但不重复计数。日活跃地址数的走势可以帮助你判断网络使用是在扩张还是萎缩，是公链和代币基本面分析中最常用的指标之一。",["不过地址不等于用户。一个人可以拥有几十个地址，",["交易所","centralized-exchange"],"一个",["热钱包","hot-wallet"],"也能代表成千上万的用户；",["空投","airdrop"],"活动期间，羊毛党批量创建地址刷交互，会让数字短期暴涨。手续费越低的链，刷地址的成本越低，数字越容易失真。"],["比较时最好同时看交易笔数、手续费收入、链上锁仓价值（",["TVL","total-value-locked"],"）和",["成交量","trading-volume"],"，并观察活跃度在活动结束后能否维持。不同数据平台的统计口径也不同，例如是否计入合约地址、是否过滤机器人。"]],"example":"假设某条公链的日活跃地址数在一个月内从40万增加到60万，涨幅50%。表面看使用量大增，但你发现同期这条链在搞积分空投活动，新增的20万个地址里，有15万个只在活动页面完成了一次小额交互，每笔转账金额都在1美元以内。活动结束两周后，日活跃地址数回落到42万，真实的自然增长只有约5%。","mistakes":["把活跃地址数等同于真实用户数。","忽略空投活动、机器人刷量对数据的短期拉动。","直接比较手续费差异很大的两条链的活跃地址数，得出片面结论。"],"faq":[{"q":"活跃地址数上升说明币价会涨吗？","a":"不一定。它反映的是网络使用情况，与价格有一定相关性，但可能受刷量影响，也可能滞后或领先价格。"},{"q":"活跃地址数和新增地址数有什么区别？","a":"新增地址数只统计首次出现在链上的地址，活跃地址数统计当期有交易行为的所有地址，包括老地址。"}],"title":"什么是活跃地址数？链上使用热度怎么看","description":"活跃地址数是什么意思？了解日活地址的统计方法、为什么地址数量不等于真实用户，以及空投刷量如何让链上数据失真。","related":[["on-chain-analysis","链上分析（On-chain analysis）","链上分析是通过研究区块链上公开记录的转账、地址余额、交易所资金流向等数据，来判断市场参与者行为和资金动向的分析方法。"],["wallet-address","钱包地址（Wallet Address）","钱包地址是区块链上用于收款的一串字符，相当于你的收款账号，由公钥计算得出，可以公开给别人，但不同链的地址格式不同。"],["trading-volume","成交量（Trading Volume）","成交量是在一段时间内实际成交的资产数量或金额，例如 24 小时成交量，用来衡量一个币或一个市场的交易活跃程度。"],["total-value-locked","总锁仓价值（TVL）","总锁仓价值（TVL）是指存放在某个 DeFi 协议或某条公链智能合约中的资产总价值，通常以美元计算，用来衡量协议规模和资金规模。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"fear-and-greed-index":{"slug":"fear-and-greed-index","cat":"onchain","en":"Fear and Greed Index","contentLocale":"zh-Hans","term":"恐惧与贪婪指数（Fear and Greed Index）","aka":["恐慌贪婪指数","贪婪恐惧指数","情绪指数"],"short":"恐惧与贪婪指数是把价格波动、成交量、社交媒体热度、资金费率等数据综合成0到100分数的市场情绪指标，分数越低代表越恐惧，越高代表越贪婪。","body":[["加密圈最常被引用的版本主要针对",["比特币","bitcoin"],"，通常把0到24划为极度恐惧，25到49为恐惧，50左右为中性，51到74为贪婪，75到100为极度贪婪。不同网站和",["交易所","centralized-exchange"],"也推出了自己的情绪指数，计算方式和权重各不相同。"],["它的用途是提醒你市场整体情绪处在什么位置。极度恐惧时，往往伴随大跌、恐慌抛售和FUD；极度贪婪时，常见FOMO追高、",["杠杆","leverage"],"率上升和",["资金费率","funding-rate"],"偏高。一些交易者把它当作逆向参考，在恐惧时更谨慎地分批布局，在贪婪时控制仓位。"],["但指数只描述情绪，不预测价格。",["牛市","bull-market"],"中它可以连续数周处在贪婪区间，",["熊市","bear-market"],"里也可能长期恐惧。把它和资金费率、未平仓合约等数据一起看，比单独依据它买卖更合理。"]],"example":"假设一周前恐惧与贪婪指数为75，BTC价格在66,000 USDT附近，资金费率普遍偏高；之后价格一周内跌到57,000 USDT，跌幅约13.6%，指数降到20，进入极度恐惧。某交易者不在情绪最差时一次性满仓，而是计划用3,000 USDT分三次、每次1,000 USDT分批买入，并预先设好仓位上限，以免被短期情绪左右。","mistakes":["看到极度恐惧就满仓抄底，看到极度贪婪就全部清仓。","不了解指数的计算来源，把不同网站的数值混在一起比较。","把情绪指数当成唯一的交易依据，忽略仓位管理和止损。"],"faq":[{"q":"恐惧与贪婪指数多少适合买入？","a":"没有固定数值。低分只说明市场情绪悲观，价格可能继续下跌，更适合作为分批、控制仓位的参考，而不是买入信号。"},{"q":"恐惧与贪婪指数多久更新一次？","a":"常见的比特币情绪指数每天更新一次，部分平台提供更高频率的版本，具体以数据来源说明为准。"}],"title":"恐惧与贪婪指数是什么？加密市场情绪怎么看","description":"恐惧与贪婪指数是什么意思？了解0到100分数的分区含义、计算参考了哪些数据，以及为什么它不能单独用来判断买卖。","related":[["fomo","FOMO（错失恐惧）","FOMO（Fear of Missing Out）指害怕错过上涨行情而冲动买入的心理，在币圈常表现为追高和临时加仓。"],["fud","FUD（恐惧、不确定、怀疑）","FUD 是 Fear、Uncertainty、Doubt 的缩写，指在市场上传播的恐惧、不确定和怀疑情绪或消息，常引发恐慌性抛售。"],["volatility","波动率（Volatility）","波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。"],["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"referral-code":{"slug":"referral-code","cat":"exchange-features","en":"Referral code (fee rebate)","contentLocale":"zh-Hans","term":"邀请码（返佣）","aka":["推荐码","返佣码","邀请链接","Referral code"],"short":"邀请码是交易所发给用户或合作方的推荐编号，新用户注册时填写后，双方可能获得手续费返佣、注册奖励等，具体权益由交易所的推荐计划规定。","body":[[["交易所","centralized-exchange"],"通过推荐计划获客：推荐人拿到一个邀请码或邀请链接，被邀请人注册时填写，之后被邀请人交易产生的手续费中，有一部分返还给推荐人，有些计划还会把一部分直接返还给被邀请人，这就是常说的“返佣”。"],"返佣比例、有效期和适用产品（现货、合约）都由交易所规定，不同计划差别很大。大多数平台只允许在注册时绑定邀请码，注册后无法补填或更换，所以如果你想享受返佣，要在注册前就确认好。","使用邀请码时要注意来源：只在交易所官方网站或官方App的注册页面填写，不要通过来路不明的链接下载App或登录，以防进入仿冒网站。返佣是降低交易成本的一种方式，但不应成为你频繁交易的理由。"],"example":["假设你每月",["合约交易","futures-contract"],"额为100,000 ",["USDT","usdt"],"，吃单手续费率为0.05%，每月手续费为50 USDT。如果注册时绑定的邀请码给被邀请人20%的手续费返还，你每月可以拿回10 USDT，实际手续费变成40 USDT，一年下来少付约120 USDT。如果你注册时没有填写邀请码，之后通常无法补绑，这部分返还也就拿不到。"],"mistakes":["注册时忘记填写邀请码，以为之后可以随时补填。","通过陌生人发的链接下载“交易所App”，进入仿冒平台。","为了多拿返佣而增加交易次数，结果亏损远超返还的手续费。"],"faq":[{"q":"注册后还能填邀请码吗？","a":"大多数交易所只允许在注册时绑定邀请码，注册后无法补填或更换，个别平台有例外，以官方规则为准。"},{"q":"使用邀请码有坏处吗？","a":"从官方渠道使用正规邀请码一般不会增加你的成本，但要警惕仿冒链接，并看清返佣的适用产品和有效期。"}],"title":"什么是交易所邀请码？手续费返佣怎么算","description":"交易所邀请码是什么？了解推荐计划和手续费返佣如何运作、返佣金额怎么计算、为什么必须在注册时绑定，以及防范仿冒链接。","related":[["maker-taker-fees","挂单费与吃单费（Maker/Taker Fee）","挂单费与吃单费是交易所按订单角色收取的两档手续费：挂在订单簿上等待成交、提供流动性的一方付挂单费，立即与已有挂单成交的一方付吃单费。"],["vip-tier","VIP等级（VIP fee tier）","VIP等级是交易所根据用户过去一段时间的交易量或资产余额划分的手续费档位，等级越高，挂单和吃单手续费率通常越低，还可能获得更高的提币额度等权益。"],["centralized-exchange","中心化交易所（CEX）","中心化交易所（CEX）是由公司运营、托管用户资产并撮合买卖订单的加密货币交易平台，如币安、OKX、Bybit、Bitget。"]],"lesson":null,"coin":null,"tool":"/rates","cta":true},"tokenized-treasuries":{"slug":"tokenized-treasuries","cat":"tokenized-assets","en":"Tokenized treasuries","contentLocale":"zh-Hans","term":"代币化美债（Tokenized treasuries）","aka":["代币化国债","链上美债","国债代币"],"short":"代币化美债是把美国短期国债或投资国债的货币市场基金份额以代币形式发行到区块链上的产品，持有者可以在链上获得接近国债利率的收益。","body":[["发行方通常设立基金或特殊目的实体，用投资者的资金买入短期美国国债或回购协议，再按份额在",["以太坊","ethereum"],"等公链上发行代币。收益可能通过代币价格逐日上涨体现，也可能通过增发代币的方式发放。贝莱德的BUIDL、Ondo Finance的相关产品是常被提及的例子。"],["相比只持有不生息的",["稳定币","stablecoin"],"，代币化美债让链上资金也能获得接近传统国债的收益，因此被DAO金库、加密基金和",["交易所","centralized-exchange"],"用作储备或抵押品。部分平台也开始接受这类代币作为合约保证金。"],"它的限制同样明显：大多数产品只向通过KYC的合格投资者开放，最低认购金额较高，转账可能只能在白名单地址之间进行；收益会随美联储利率变化，扣除管理费后才是你的实际收益；赎回可能需要按工作日处理。"],"example":["假设某代币化美债产品的底层国债年化收益为4.5%，管理费为每年0.15%，净收益约4.35%。你投入100,000 ",["USDC","usdc"],"，持有一年预期收益约4,350美元；如果同样的资金一直放在钱包里持有USDC，自身不产生收益。若一年后利率下降到3.5%，在同样费率下净收益约3.35%，相同本金的年收益就会降到约3,350美元。"],"mistakes":["把代币化美债的收益当成固定利率，忽视利率变化带来的收益下降。","不了解产品只对合格投资者开放，在非官方渠道高价购买。","以为可以像USDC一样随时任意转账，忽略白名单和赎回时间限制。"],"faq":[{"q":"代币化美债和稳定币有什么区别？","a":"稳定币通常不向持有者支付收益，价值固定为1美元；代币化美债把国债收益传递给持有者，但通常有KYC和投资者资格限制。"},{"q":"普通人能买代币化美债吗？","a":"许多产品只向合格投资者或机构开放，也有部分产品面向更广泛的非美国用户，具体资格以发行方说明为准。"}],"title":"什么是代币化美债？链上国债收益与限制","description":"代币化美债是什么？了解国债代币如何把美国短期国债收益带到链上、收益如何计算、与稳定币的区别以及KYC和赎回限制。","related":[["real-world-assets","现实世界资产（RWA）","现实世界资产（RWA）是指被代币化后在区块链上发行和流通的链下资产，例如国债、货币市场基金、私人信贷、房地产、黄金和股票等。"],["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"],["apr-vs-apy","APR 和 APY 的区别","APR 是不计复利的年化收益率，APY 是计入复利后的年化收益率；同一个利率下，复利频率越高，APY 就比 APR 高得越多。"],["kyc","KYC（了解你的客户）","KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。"]],"lesson":null,"coin":{"slug":"ondo","name":"Ondo","symbol":"ONDO"},"tool":"/topics/tokenized-treasuries","cta":false}});
